
Ext.ns("Ext.Cont.Comprobante");Ext.Cont.Comprobante.Tool={init:function(b){Ext.QuickTips.init();var a=this;a.url="/contabilidad/contabilidad_financiera/comprobante_operaciones/index.php/mostrarcomprobante/";a.perfil=window.parent.perfil;Ext.CONT.Componentes.MessageBox("msgLoading","Cargando datos del comprobante...","Por favor espere");Ext.Ajax.request({method:"POST",url:a.url+"loadComprobanteExterno",params:{idcomprobante:b},callback:function(d,e,c){this.responseData=Ext.decode(c.responseText);if(this.responseData.pases.length>0){Ext.Cont.Comprobante.init(this.responseData.idsubsistema,this.responseData.detalle,this.responseData.observacion,this.responseData.fecha,this.responseData.pases,3,1,0,this.responseData.estado,b)}Ext.CONT.Componentes.HideBox("msgLoading")}});return this}};